<?php
require "includes/db.php";if(session_status()===PHP_SESSION_NONE)session_start();if(empty($_SESSION['user'])){header("Location:login.php");exit;}if(empty($_SESSION['cart'])){header("Location:cart.php");exit;}
$ids=array_keys($_SESSION['cart']);$ph=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$s=$conn->prepare("SELECT * FROM products WHERE product_id IN ($ph)");$s->bind_param($types,...$ids);$s->execute();$r=$s->get_result();$items=[];$total=0;while($p=$r->fetch_assoc()){$p['qty']=$_SESSION['cart'][$p['product_id']];$total+=$p['qty']*$p['price'];$items[]=$p;}
$error="";if($_SERVER['REQUEST_METHOD']==='POST'){$address=trim($_POST['address']);$payment=$_POST['payment'];if(!$address)$error="Please enter your address.";else{$conn->begin_transaction();try{$s=$conn->prepare("INSERT INTO orders(user_id,total_amount,status,payment_method,address) VALUES(?,?, 'Pending',?,?)");$s->bind_param("idss",$_SESSION['user']['id'],$total,$payment,$address);$s->execute();$oid=$s->insert_id;$it=$conn->prepare("INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)");foreach($items as $p)$it->bind_param("iiid",$oid,$p['product_id'],$p['qty'],$p['price'])||$it->execute();$conn->commit();$_SESSION['cart']=[];header("Location:order_success.php?id=$oid");exit;}catch(Throwable $e){$conn->rollback();$error="Unable to place order.";}}}
$pageTitle="Checkout | Artisan Brew Co.";require "includes/header.php";?>
<section class="form-page"><div class="form-card wide"><p class="eyebrow">FINAL STEP</p><h1>Check <em>Out.</em></h1><?php if($error):?><div class="alert"><?=$error?></div><?php endif;?><p class="checkout-total">Order total: <strong>$<?=number_format($total,2)?></strong></p><form method="post"><label>Delivery Address<textarea name="address" rows="4" required></textarea></label><label>Payment Method<select name="payment"><option>Cash on Delivery</option><option>Card (Demo)</option><option>GCash (Demo)</option></select></label><button class="btn dark">Place Order</button></form></div></section><?php require "includes/footer.php";?>